def render_banner(hw_info: Optional[HardwareInfo] = None) -> str:
    """Builds and returns the complete side-by-side FlexSDS banner."""
    if hw_info is None:
        hw_info = detect_hardware()

    gpu_str = hw_info.summary()

    info_lines = [
        "\033[1;37m  ███████╗██╗     ███████╗██╗  ██╗███████╗██████╗ ███████╗\033[0m",
        "\033[1;37m  ██╔════╝██║     ██╔════╝╚██╗██╔╝██╔════╝██╔══██╗██╔════╝\033[0m",
        "\033[1;37m  █████╗  ██║     █████╗   ╚███╔╝ ███████╗██║  ██║███████╗\033[0m",
        "\033[1;37m  ██╔══╝  ██║     ██╔══╝   ██╔██╗ ╚════██║██║  ██║╚════██║\033[0m",
        "\033[1;37m  ██║     ███████╗███████╗██╔╝ ██╗███████║██████╔╝███████║\033[0m",
        "",
        "  \033[1;37mFlexSDS\033[0m \033[90m· Speculative Decoding Serving Engine · v0.2.0-alpha\033[0m",
        "  \033[90mNhóm đồ án D22\033[0m",
        "  \033[90mHọc viện Công nghệ Bưu chính Viễn thông (PTIT)\033[0m",
        "",
        f"  \033[90m•\033[0m \033[37mHardware\033[0m    : \033[90m{gpu_str}\033[0m",
        "  \033[90m•\033[0m \033[37mEngine\033[0m      : \033[90mTreeAdaptive v0.2\033[0m",
        "  \033[90m•\033[0m \033[37mBackends\033[0m    : \033[90mModal / Colab / Local vLLM\033[0m",
    ]

    max_rows = max(len(PTIT_LOGO_ANSI), len(info_lines))
    col_logo = list(PTIT_LOGO_ANSI) + [" " * 26] * (max_rows - len(PTIT_LOGO_ANSI))
    col_info = list(info_lines) + [""] * (max_rows - len(info_lines))

    output = []
    for l, r in zip(col_logo, col_info):
        output.append(f" {l}  {r}")
    return "\n".join(output)


def print_banner(hw_info: Optional[HardwareInfo] = None) -> None:
    """Prints the banner directly to stdout."""
    print(render_banner(hw_info))


if __name__ == "__main__":
    print_banner()
